<main id="main" class="container section"><div class="section-heading"><div><div class="eyebrow"><?= e(t('HOSPITAL OVERVIEW')) ?></div><h1><?= e(t('A good day for better care.')) ?></h1><p class="muted"><?= e(date_label(today())) ?> <?= e(t('· Pakistan Standard Time')) ?></p></div><a class="btn btn-primary" href="<?= e(url('admin/doctors.php')) ?>"><?= e(t('+ Add doctor')) ?></a></div><div class="metrics"><div class="metric"><span><?= e(t('Active doctors')) ?></span><strong><?= $active ?></strong><small><?= e(t('Available in your directory')) ?></small></div><div class="metric"><span><?= e(t('Appointments today')) ?></span><strong><?= e($counts['total']) ?></strong><small><?= e(t('Includes cancelled bookings')) ?></small></div><div class="metric"><span><?= e(t('Patients booked today')) ?></span><strong><?= e($counts['patients']) ?></strong><small><?= e(t('Unique mobiles · excludes cancelled')) ?></small></div><div class="metric"><span><?= e(t('Consultations completed')) ?></span><strong><?= e($counts['completed']) ?></strong><small><?= e(t('Today’s completed visits')) ?></small></div></div><div class="panel"><div class="section-heading"><div><h2><?= e(t('Today’s doctor schedules')) ?></h2><p class="muted mb-0"><?= e(t('A clear view of the day ahead.')) ?></p></div><a class="text-link" href="<?= e(url('admin/schedules.php')) ?>"><?= e(t('Manage schedules ↗')) ?></a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th><?= e(t('Doctor')) ?></th><th><?= e(t('Booking window')) ?></th><th><?= e(t('Consultation')) ?></th><th><?= e(t('Appointments')) ?></th><th><?= e(t('Status')) ?></th><th></th></tr></thead><tbody><?php $shown=0; foreach($doctors as $d): $s=schedule_for((int)$d['id'],today()); if(!$s) continue; $shown++; $state=booking_state((int)$d['id'],today()); $n=one("SELECT COUNT(*) n FROM appointments WHERE doctor_id=? AND appointment_date=? AND status <> 'Cancelled'",[$d['id'],today()])['n']; ?><tr><td><strong><?= e($d['name']) ?></s